//! Optional catalog entry only. Synthetic in-memory records, no source/profile mapping.
use nxt_os::{store::Store,tax::{Tax,catalog,models::*,family_workflow::{MembersInput,PairedInputs}}};
use serde_json::{json,Value};use sha2::{Digest,Sha256};
const KEYS:&[&str]=&["self_employment_gross_cents","self_employment_expenses_cents","self_employment_cca_cents","t2125_verified","se_cpp_deduction_cents","se_cpp_credit_cents","se_cpp_verified","rental_gross_cents","rental_expenses_cents","rental_cca_cents","t776_verified","medical_expenses_cents","donations_cents","tuition_cents","credits_verified"];
fn input(name:&str,inputs:Value)->ReturnInput{serde_json::from_value(json!({"program":"T1","tax_year":2025,"jurisdiction":"AB","name":name,"client_ref":"A","inputs":inputs})).unwrap()}
fn digest(b:&[u8])->String{hex::encode(Sha256::digest(b))}
#[test]fn optional_fields_leave_existing_defaults_and_schema_identity_unchanged(){
 let c=catalog::catalog();let p=&c["programs"][0];assert_eq!(p["entry_schema_id"],"nxt-tax-entry/T1/2025/v1");assert_eq!(p["field_catalog_version"],catalog::T1_FIELD_CATALOG_VERSION);
 let defaults=json!({"scope_confirmed":false,"other_tax_situations":false,"full_year_resident":false,"provincial_adjustments_not_applicable":false,"employment_income_cents":0,"interest_income_cents":0,"rrsp_deduction_cents":0,"rrsp_deduction_limit_cents":0,"rrsp_verified":false,"cpp_enhanced_deduction_cents":0,"cpp_base_credit_cents":0,"ei_credit_cents":0,"payroll_verified":false,"tax_withheld_cents":0,"instalments_cents":0});assert_eq!(p["defaults"],defaults);
 let fields:Vec<_>=p["sections"].as_array().unwrap().iter().flat_map(|s|s["fields"].as_array().unwrap()).filter(|f|f["optional"]==true).collect();assert_eq!(fields.len(),49);
 for key in KEYS.iter().chain(["schedule8_part4_verified","t2125_itemized_verified","t2125_8521_cents"].iter()) {let f=fields.iter().find(|f|f["key"]==*key).unwrap();assert_eq!(f["default_policy"],"omit");assert!(f.get("default").is_none());assert!(p["defaults"].get(*key).is_none());assert_eq!(f["tax_years"],json!([2025]));assert!(!f["jurisdictions"].as_array().unwrap().contains(&json!("QC")));assert!(p["input_schema"]["properties"].get(*key).is_some());}
 for held in ["spouse_net_income_cents","rrsp_prior_year_earned_income_cents","eligible_dividends_cents","foreign_non_business_income_cents"]{assert!(p["input_schema"]["properties"].get(held).is_none());}
 if let Ok(dir)=std::env::var("NXT_OPTIONAL_WORKPAPER_FIXTURE_DIR"){let path=std::path::Path::new(&dir);std::fs::create_dir_all(path).unwrap();std::fs::write(path.join("catalog.json"),serde_json::to_vec(&c).unwrap()).unwrap();}
}
#[tokio::test]async fn old_literal_input_hash_stays_exact_and_optional_zero_and_absence_roundtrip(){
 let old=r#"{"program":"T1","tax_year":2025,"jurisdiction":"AB","name":"Synthetic legacy","client_ref":"A","period_start":null,"period_end":null,"inputs":{"employment_income_cents":0,"scope_confirmed":false},"parties":[],"corporate":null,"notes":"","expected_revision":null}"#;
 const OLD_SHA:&str="d5d5b77a9c33e152357fb0f99b729d3319a3993984d783052fa6ff1e9c3a374d";let doc:ReturnInput=serde_json::from_str(old).unwrap();assert_eq!(digest(old.as_bytes()),OLD_SHA);assert_eq!(serde_json::to_vec(&doc).unwrap(),old.as_bytes());
 let t=Tax::new(Store::memory());let r=t.save(None,doc).await.unwrap_or_else(|e|panic!("{}",e.1));let mut unchanged=ReturnInput::from(&r);unchanged.expected_revision=Some(r.revision);let r=t.save(Some(&r.id),unchanged).await.unwrap_or_else(|e|panic!("{}",e.1));assert_eq!(serde_json::to_vec(&ReturnInput::from(&r)).unwrap(),old.as_bytes());
 let calc=t.calculate(&r.id,RevisionInput{expected_revision:r.revision,idempotency_key:None}).await.unwrap_or_else(|e|panic!("{}",e.1));assert_eq!(calc.calculation.as_ref().unwrap().input_hash,OLD_SHA);
 let mut edit=ReturnInput::from(&calc);edit.expected_revision=Some(calc.revision);edit.inputs["rental_gross_cents"]=json!(0);let zero=t.save(Some(&r.id),edit).await.unwrap_or_else(|e|panic!("{}",e.1));assert_eq!(zero.inputs["rental_gross_cents"],0);assert!(zero.inputs.get("t776_verified").is_none());assert_ne!(digest(&serde_json::to_vec(&ReturnInput::from(&zero)).unwrap()),OLD_SHA);
 let mut clear=ReturnInput::from(&zero);clear.expected_revision=Some(zero.revision);clear.inputs.as_object_mut().unwrap().remove("rental_gross_cents");let r=t.save(Some(&r.id),clear).await.unwrap_or_else(|e|panic!("{}",e.1));assert_eq!(serde_json::to_vec(&ReturnInput::from(&r)).unwrap(),old.as_bytes());
}
#[tokio::test]async fn existing_rental_and_credit_paths_preserve_inputs_and_require_explicit_verification(){
 for jurisdiction in ["AB","ON","BC"]{let t=Tax::new(Store::memory());let mut d=input("Synthetic optional",json!({"scope_confirmed":true,"full_year_resident":true,"provincial_adjustments_not_applicable":true,"employment_income_cents":5000000,"rental_gross_cents":100000,"rental_expenses_cents":20000,"rental_cca_cents":10000,"medical_expenses_cents":100000,"donations_cents":20000,"tuition_cents":5000}));d.jurisdiction=jurisdiction.into();let r=t.save(None,d).await.unwrap_or_else(|e|panic!("{}",e.1));assert!(r.inputs.get("t776_verified").is_none()&&r.inputs.get("credits_verified").is_none());let calc=t.calculate(&r.id,RevisionInput{expected_revision:r.revision,idempotency_key:None}).await.unwrap_or_else(|e|panic!("{}",e.1));assert_eq!(calc.calculation.as_ref().unwrap().result["supported"],false);
 let mut edit=ReturnInput::from(&calc);edit.expected_revision=Some(calc.revision);edit.inputs["t776_verified"]=json!(true);edit.inputs["credits_verified"]=json!(true);let r=t.save(Some(&calc.id),edit).await.unwrap_or_else(|e|panic!("{}",e.1));assert!(r.calculation.is_none()&&r.review.is_none());let result=t.calculate(&r.id,RevisionInput{expected_revision:r.revision,idempotency_key:None}).await.unwrap_or_else(|e|panic!("{}",e.1));assert_eq!(result.calculation.as_ref().unwrap().result["totals"]["taxable_income"],5070000);assert_eq!(result.inputs["tuition_cents"],5000);}
}
#[tokio::test]async fn paired_optional_clear_is_explicit_and_cannot_remove_baseline_or_group_owned_values(){
 let t=Tax::new(Store::memory());let a=t.save(None,input("Synthetic A",json!({"employment_income_cents":100000,"medical_expenses_cents":12345,"credits_verified":false}))).await.unwrap_or_else(|e|panic!("{}",e.1));let b=t.save(None,input("Synthetic B",json!({"employment_income_cents":200000}))).await.unwrap_or_else(|e|panic!("{}",e.1));
 let w=t.save_family_members(None,MembersInput{label:"Synthetic optional pair".into(),primary_return_id:a.id.clone(),spouse_return_id:b.id.clone(),expected_primary_revision:a.revision,expected_spouse_revision:b.revision,expected_client_ref:"A".into(),expected_family_sha256:None}).await.unwrap_or_else(|e|panic!("{}",e.1));let fid=w["family"]["id"].as_str().unwrap();let request=||serde_json::from_value::<PairedInputs>(json!({"expected_family_sha256":w["family_sha256"],"expected_primary_revision":a.revision,"expected_spouse_revision":b.revision,"expected_client_ref":"A","primary_inputs":a.inputs,"spouse_inputs":b.inputs})).unwrap();
 let mut bad=request();bad.primary_inputs.as_object_mut().unwrap().remove("employment_income_cents");assert!(t.save_family_pair(fid,bad).await.is_err());let mut clear=request();clear.primary_inputs.as_object_mut().unwrap().remove("medical_expenses_cents");clear.primary_inputs.as_object_mut().unwrap().remove("credits_verified");clear.spouse_inputs["medical_expenses_cents"]=json!(0);let saved=t.save_family_pair(fid,clear).await.unwrap_or_else(|e|panic!("{}",e.1));assert!(saved["primary"]["inputs"].get("medical_expenses_cents").is_none());assert!(saved["primary"]["inputs"].get("credits_verified").is_none());assert_eq!(saved["spouse"]["inputs"]["medical_expenses_cents"],0);
 let mut d=input("Synthetic tuition group",json!({}));d.slip_groups=Some(serde_json::from_value(json!([{"kind":"T2202","issuer":"Synthetic school","boxes":{"23":100}}])).unwrap());let r=t.save(None,d).await.unwrap_or_else(|e|panic!("{}",e.1));let mut x=ReturnInput::from(&r);x.expected_revision=Some(r.revision);x.inputs.as_object_mut().unwrap().remove("tuition_cents");let preserved=t.save(Some(&r.id),x).await.unwrap_or_else(|e|panic!("{}",e.1));assert_eq!(preserved.inputs["tuition_cents"],100);
}
